CREATE TABLE teams(id TEXT PRIMARY KEY,name TEXT COLLATE NOCASE UNIQUE NOT NULL,leader TEXT NOT NULL,friendly_fire INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,kills INTEGER NOT NULL DEFAULT 0,deaths INTEGER NOT NULL DEFAULT 0,wins INTEGER NOT NULL DEFAULT 0);
CREATE TABLE team_members(player TEXT PRIMARY KEY,team TEXT NOT NULL REFERENCES teams(id),role TEXT NOT NULL CHECK(role IN ('LEADER','OFFICER','MEMBER')),joined INTEGER NOT NULL);
CREATE TABLE team_invitations(team TEXT NOT NULL REFERENCES teams(id),player TEXT NOT NULL,inviter TEXT NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(team,player));
CREATE TABLE team_creations(player TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE team_combat(player TEXT PRIMARY KEY,until_time INTEGER NOT NULL);
CREATE TABLE team_relations(a TEXT NOT NULL,b TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('ALLY_REQUEST','ALLY','RIVAL','WAR_REQUEST','WAR','FINISHED')),expires INTEGER NOT NULL,score_a INTEGER NOT NULL DEFAULT 0,score_b INTEGER NOT NULL DEFAULT 0,winner TEXT,PRIMARY KEY(a,b,kind));
CREATE TABLE team_deaths(id TEXT PRIMARY KEY,killer TEXT NOT NULL,victim TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX team_roster ON team_members(team);
